output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to check out the cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": "at(1,5)",
        "cart_waiting_at_entry": "cartAt(1,5)",
        "has_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "cart_waiting_at_entry",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "must_return_cart_to_bay",
    "text": "After taking the cart, the shopper is obliged to return it to the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": "at(1,5)",
        "cart_waiting_at_entry": "cartAt(1,5)",
        "has_cart": "hasCart",
        "at_return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "cart_waiting_at_entry"
            ]
          },
          "post": "has_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "has_cart",
              "at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "It is forbidden to leave a cart anywhere other than the designated return bay.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "has_cart",
              "LEAVE_CART",
              {
                "not": "at_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to leave the supermarket while still possessing the shopping cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "has_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "items_require_cart",
    "text": "It is forbidden to pick up shelf items unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "It is forbidden to carry groceries by hand instead of placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "has_cart": "hasCart"
      },
      "events": {
        "pickup_into_hands": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_into_hands"
        ]
      }
    }
  },
  {
    "id": "after_item_return_cart",
    "text": "Whenever an item has been picked up using the cart, the shopper is obliged to return the cart to the return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "at_return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "item_collected_with_cart": {
          "pre": {
            "and": [
              "has_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "cart_returned_after_shopping": {
          "pre": {
            "and": [
              "has_cart",
              "at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected_with_cart",
      "discharge": "cart_returned_after_shopping"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once the cart is stationed in the return bay, it is forbidden to pick it up again.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "at_return_bay",
              "cart_in_return_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
